// Compose an OpenAI-style chat request for the Hugging Face router.
// System = docs/ASSISTANT-CORE.md (role + ops protocol) + docs/LLM-AUTHORING.md
// (the live spec), both fetched fresh from GitHub Pages. Model settings come
// from the Model node — the only place to touch when switching models.
const core = String($('Fetch core prompt').first().json.data || '');
const spec = String($('Fetch authoring spec').first().json.data || '');
const cfg = $('Model').first().json;
const req = $('Webhook').first().json.body || {};

const messages = [{
  role: 'system',
  content: core + '\n\nAUTHORITATIVE WEFT AUTHORING SPEC (node types, ports, list semantics):\n\n' + spec
}];
for (const t of req.history || []) {
  if (t && t.text) messages.push({ role: t.role === 'assistant' ? 'assistant' : 'user', content: String(t.text) });
}
const text = 'CURRENT GRAPH (weft format 2):\n' + JSON.stringify(req.graph || { nodes: [], wires: [] })
  + '\n\nSELECTED NODE IDS: ' + JSON.stringify(req.selection || [])
  + '\n\nLIVE EVAL ERRORS: ' + JSON.stringify(req.errors || {})
  + '\n\nUSER MESSAGE:\n' + String(req.message || '');
// the cloth snapshot only goes to models that can see (Model.vision = true)
const wantsImage = cfg.vision === true && typeof req.snapshot === 'string' && req.snapshot.indexOf('data:image/jpeg;base64,') === 0;
messages.push(wantsImage
  ? { role: 'user', content: [{ type: 'image_url', image_url: { url: req.snapshot } }, { type: 'text', text }] }
  : { role: 'user', content: text });

const body = {
  model: cfg.model,
  messages,
  max_tokens: Number(cfg.max_tokens) || 8000,
  temperature: Number(cfg.temperature) || 0.2
};
if (cfg.reasoning_effort) body.reasoning_effort = cfg.reasoning_effort;
return [{ json: { body } }];

// Split the model's answer into reply text + the weft-ops block (if any).
// Tolerates the JS-isms open models slip into (// comments, trailing
// commas) — mirrors WeftOps.tidyJSON in js/ops.js. If the block still won't
// parse, ops is null and the fence stays in the reply so the panel gets a go.
const choice = ($json.choices || [])[0] || {};
const text = String((choice.message || {}).content || '');
const tidy = s => {
  let out = '', inStr = false, i = 0;
  while (i < s.length) {
    const c = s[i];
    if (inStr) { out += c; if (c === '\\') { out += s[i + 1] || ''; i += 2; continue; } if (c === '"') inStr = false; i++; }
    else if (c === '"') { inStr = true; out += c; i++; }
    else if (c === '/' && s[i + 1] === '/') { while (i < s.length && s[i] !== '\n') i++; }
    else if (c === '/' && s[i + 1] === '*') { const j = s.indexOf('*/', i + 2); i = j < 0 ? s.length : j + 2; }
    else { out += c; i++; }
  }
  return out.replace(/,(\s*[\]}])/g, '$1');
};
const pick = p => Array.isArray(p) ? p : (p && Array.isArray(p.ops) ? p.ops : null);
let reply = text.trim();
let ops = null;
const m = text.match(/```(?:weft-ops|json)?[ \t]*\n([\s\S]*?)```/);
if (m) {
  try { ops = pick(JSON.parse(m[1])); } catch (e) { try { ops = pick(JSON.parse(tidy(m[1]))); } catch (e2) { ops = null; } }
  if (ops) reply = text.replace(m[0], '').trim();
}
if (choice.finish_reason === 'length' && !ops) reply += '\n\n(the model ran out of output tokens mid-answer — try again or ask for a smaller change)';
return [{ json: { reply, ops, model: $json.model || '', finish: choice.finish_reason || '' } }];
